// Semantic tokens / declarations, types and doc comments
import { semanticTokenCases } from "../../harness";

const SAMPLE = [
    "interface Logger {",
    "  function log(str: string): void;",
    "}",
    "class Counter extends Base implements Sized {",
    "  private count: number = 0;",
    "  weak parent: Counter;",
    "  static function increment(): void { Counter.count = Counter.count + 1; }",
    "  get value(): number { return this.count; }",
    "}",
    "enum Color { Red, Green, Blue }",
    "type Name = string;",
    "function addTen(ref x: number) {",
    "  x = x + 10;",
    "}",
    "async function countdown(from: number): Promise<void> {",
    "  let n = from;",
    "  while (n > 0) {",
    "    await sleep(100);",
    "    n = n - 1;",
    "  }",
    "  for (let item of [1, 2]) { print(item); }",
    "  try { risky(); } catch (e) { print(e); } finally { print(\"done\"); }",
    "}",
    "let e = new EventEmitter();",
    "e.on(\"greet\", (name) => console.log(name));",
].join("\n");

semanticTokenCases("Semantic tokens: declarations and types", [
    { name: "interface keyword scopes as a storage type", source: SAMPLE, expectScopes: [["interface", "storage.type.interface.cp3"]] },
    { name: "Logger interface name scopes as a type", source: SAMPLE, expectScopes: [["Logger", "entity.name.type.interface.cp3"]] },
    { name: "log member declaration scopes as a function name", source: SAMPLE, expectScopes: [["log", "entity.name.function.cp3"]] },
    { name: "str parameter scopes as a parameter", source: SAMPLE, expectScopes: [["str", "variable.parameter.cp3"]] },
    { name: "class keyword scopes as a storage type", source: SAMPLE, expectScopes: [["class", "storage.type.class.cp3"]] },
    { name: "extends scopes as a modifier", source: SAMPLE, expectScopes: [["extends", "storage.modifier.extends.cp3"]] },
    { name: "implements scopes as a modifier", source: SAMPLE, expectScopes: [["implements", "storage.modifier.extends.cp3"]] },
    { name: "private scopes as a member modifier", source: SAMPLE, expectScopes: [["private", "storage.modifier.cp3"]] },
    { name: "static scopes as a member modifier", source: SAMPLE, expectScopes: [["static", "storage.modifier.cp3"]] },
    { name: "weak scopes as a member modifier", source: SAMPLE, expectScopes: [["weak", "storage.modifier.cp3"]] },
    { name: "ref scopes as a member modifier", source: SAMPLE, expectScopes: [["ref", "storage.modifier.cp3"]] },
    { name: "async scopes as a member modifier", source: SAMPLE, expectScopes: [["async", "storage.modifier.cp3"]] },
    { name: "Counter scopes as a class name", source: SAMPLE, expectScopes: [["Counter", "entity.name.class.cp3"]] },
    { name: "Base scopes as an inherited-class reference", source: SAMPLE, expectScopes: [["Base", "entity.other.inherited-class.cp3"]] },
    { name: "Sized scopes as an inherited-class reference", source: SAMPLE, expectScopes: [["Sized", "entity.other.inherited-class.cp3"]] },
    { name: "increment scopes as a function name", source: SAMPLE, expectScopes: [["increment", "entity.name.function.cp3"]] },
    { name: "value accessor scopes as a function name", source: SAMPLE, expectScopes: [["value", "entity.name.function.cp3"]] },
    { name: "this scopes as a language variable", source: SAMPLE, expectScopes: [["this", "variable.language.this.cp3"]] },
    { name: "count property scopes as a property", source: SAMPLE, expectScopes: [["count", "variable.other.property.cp3"]] },
    { name: "enum keyword scopes as a storage type", source: SAMPLE, expectScopes: [["enum", "storage.type.enum.cp3"]] },
    { name: "Color scopes as an enum type", source: SAMPLE, expectScopes: [["Color", "entity.name.type.enum.cp3"]] },
    { name: "Red scopes as an enum member", source: SAMPLE, expectScopes: [["Red", "variable.other.enummember.cp3"]] },
    { name: "type alias keyword scopes as storage", source: SAMPLE, expectScopes: [["type", "storage.type.cp3"]] },
    { name: "Name scopes as a type alias", source: SAMPLE, expectScopes: [["Name", "entity.name.type.alias.cp3"]] },
    { name: "number primitive scopes as a primitive type", source: SAMPLE, expectScopes: [["number", "support.type.primitive.cp3"]] },
    { name: "string primitive scopes as a primitive type", source: SAMPLE, expectScopes: [["string", "support.type.primitive.cp3"]] },
    { name: "void scopes as a primitive type", source: SAMPLE, expectScopes: [["void", "support.type.primitive.cp3"]] },
    { name: "while scopes as control flow", source: SAMPLE, expectScopes: [["while", "keyword.control.cp3"]] },
    { name: "try scopes as control flow", source: SAMPLE, expectScopes: [["try", "keyword.control.cp3"]] },
    { name: "catch scopes as control flow", source: SAMPLE, expectScopes: [["catch", "keyword.control.cp3"]] },
    { name: "finally scopes as control flow", source: SAMPLE, expectScopes: [["finally", "keyword.control.cp3"]] },
    { name: "await scopes as control flow", source: SAMPLE, expectScopes: [["await", "keyword.control.cp3"]] },
    { name: "sleep scopes as a builtin function", source: SAMPLE, expectScopes: [["sleep", "support.function.builtin.cp3"]] },
    { name: "EventEmitter scopes as a builtin class", source: SAMPLE, expectScopes: [["EventEmitter", "support.class.builtin.cp3"]] },
    { name: "on scopes as a function name", source: SAMPLE, expectScopes: [["on", "entity.name.function.cp3"]] },
    { name: "the type annotation colon scopes as a type annotation", source: SAMPLE, expectScopes: [[":", "keyword.operator.type.annotation.cp3"]] },
    { name: "function scopes as a storage type", source: SAMPLE, expectScopes: [["function", "storage.type.function.cp3"]] },
    { name: "addTen scopes as a function name", source: SAMPLE, expectScopes: [["addTen", "entity.name.function.cp3"]] },
    { name: "x parameter scopes as a parameter", source: SAMPLE, expectScopes: [["x", "variable.parameter.cp3"]] },
    { name: "countdown scopes as a function name", source: SAMPLE, expectScopes: [["countdown", "entity.name.function.cp3"]] },
    { name: "from parameter scopes as a parameter", source: SAMPLE, expectScopes: [["from", "variable.parameter.cp3"]] },
    { name: "n variable scopes as a readwrite variable", source: SAMPLE, expectScopes: [["n", "variable.other.readwrite.cp3"]] },
    { name: "item loop variable scopes as a readwrite variable", source: SAMPLE, expectScopes: [["item", "variable.other.readwrite.cp3"]] },
    { name: "risky call scopes as a function name", source: SAMPLE, expectScopes: [["risky", "entity.name.function.cp3"]] },
    { name: "Promise scopes as a type", source: SAMPLE, expectScopes: [["Promise", "entity.name.type.cp3"]] },
    { name: "of in a for-of loop scopes as a keyword operator", source: SAMPLE, expectScopes: [["of", "keyword.operator.expression.of.cp3"]] },
]);
